    private SoundEventKeys() {
        throw new UnsupportedOperationException("SoundEventKeys cannot be instantiated.");
    }

    private static TypedKey<SoundEvent> create(@KeyPattern final String value) {
        return TypedKey.create(RegistryKey.SOUND_EVENT, value);
    }

    /**
     * Returns a stream containing all keys declared by this class.
     *
     * @return a stream of registry keys
     */
    public static Stream<TypedKey<SoundEvent>> values() {
        return VALUES.stream();
    }
